  async function exportFile(){
    if(document.activeElement?.classList?.contains('pdf-text-box'))document.activeElement.blur();const out=els.format.value,base=safeName(state.file.name);busy(true,'Đang tạo file tải xuống…');
    try{
      if(out==='docx-editable')await exportEditableDocx(base);
      else if(out==='docx-fidelity')await exportVisualDocx(base);
      else if(state.type==='media')await exportMedia(out,base);
      else if(state.type==='spreadsheet'){
        if(['xlsx','xls','ods','csv'].includes(out))exportSpreadsheet(out,base);
        else if(out==='html')saveBlob(new Blob([`<!doctype html><meta charset="utf-8"><body>${safeHtml(els.doc.innerHTML)}</body>`],{type:'text/html;charset=utf-8'}),`${base}.html`);
        else await exportDocPdf(base);
      }else if(state.type==='document'){
        if(out==='svg'&&state.dxfSvg)saveBlob(new Blob([state.dxfSvg],{type:'image/svg+xml;charset=utf-8'}),`${base}.svg`);
        else if(out==='txt')saveBlob(new Blob([state.dxfSvg?new TextDecoder().decode(state.sourceBytes):els.doc.innerText],{type:'text/plain;charset=utf-8'}),`${base}.txt`);
        else if(out==='html')saveBlob(new Blob([`<!doctype html><meta charset="utf-8"><title>${escapeHtml(base)}</title><body>${els.doc.innerHTML}</body>`],{type:'text/html;charset=utf-8'}),`${base}.html`);
        else if(out==='doc')exportWordHtml(els.doc.innerHTML,base);
        else await exportDocPdf(base);
      }else if(out==='doc-layout')await exportPdfLayoutWordV31(base);
      else if(out==='doc')await exportPdfWord(base);
      else if(out==='pdf'||out==='pdf-compact') await exportPdf(base);
      else if(out==='svg') await exportSvg(base);
      else saveBlob(await canvasBlob(out),`${base}.${out}`);
      toast('Đã tạo file tải xuống');
    }catch(e){console.error(e);toast('Không thể xuất file: '+e.message)}finally{busy(false)}
  }
  async function exportDocPdf(base){const shot=await html2canvas(els.doc,{scale:1.5,backgroundColor:'#ffffff',useCORS:true});const {jsPDF}=window.jspdf;const pdf=new jsPDF({unit:'px',format:'a4',orientation:'portrait'}),pw=pdf.internal.pageSize.getWidth(),ph=pdf.internal.pageSize.getHeight(),ratio=pw/shot.width,pagePx=ph/ratio,q=+els.quality.value/100;for(let y=0,page=0;y<shot.height;y+=pagePx,page++){if(page)pdf.addPage();pdf.addImage(shot.toDataURL('image/jpeg',q),'JPEG',0,-y*ratio,pw,shot.height*ratio)}pdf.save(`${base}.pdf`)}
  function exportWordHtml(html,base){const content=`<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word"><head><meta charset="utf-8"><title>${escapeHtml(base)}</title><style>body{font-family:Arial,sans-serif;line-height:1.55}img{max-width:100%}table{border-collapse:collapse}td,th{border:1px solid #999;padding:6px}</style></head><body>${html}</body></html>`;saveBlob(new Blob(['\ufeff',content],{type:'application/msword'}),`${base}.doc`)}
