  async function exportPdfLayoutWord(base){await ensureAllPdfPages();let html='<style>.pdf-word-page{position:relative;margin:0 auto 18px;page-break-after:always;overflow:hidden}.pdf-word-page>img{position:absolute;inset:0;width:100%;height:100%}.pdf-word-text{position:absolute;z-index:2;background:#fff;white-space:pre;line-height:1}</style>';for(let i=1;i<=state.pages;i++){const entry=state.pageElements[i],page=entry.page||await state.pdf.getPage(i),vp=entry.vp||page.getViewport({scale:state.renderScale}),content=await page.getTextContent();html+=`<div class="pdf-word-page" style="width:${vp.width}px;height:${vp.height}px"><img src="${entry.base.toDataURL('image/png')}">`;for(const item of content.items){if(!item.str?.trim())continue;const tx=pdfjsLib.Util.transform(vp.transform,item.transform),size=Math.max(6,Math.hypot(tx[2],tx[3])),width=Math.max(4,item.width*vp.scale);html+=`<span class="pdf-word-text" style="left:${tx[4]}px;top:${tx[5]-size}px;width:${width+4}px;height:${size*1.2}px;font-size:${size}px">${escapeHtml(item.str)}</span>`}html+='</div>'}exportWordHtml(html,base)}
